import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { useSheetDueTotal } from '../rates/due.slot';
import { useSheetOverdue } from '../rates/overdue.slot';
import { STATUSES, statusCount } from '../summary/summary.slot';

/**
 * Counters shown at the top of the sheet at all times. Each repeats a figure shown elsewhere and is
 * worked out the same way: people on the sheet (retired included), claims per status as in the
 * summary, and the sheet's due- and overdue-totals.
 */
function Header({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const dueTotal = useSheetDueTotal(sheetId);
  const { total: overdueTotal } = useSheetOverdue(sheetId);

  return (
    <header data-testid="header">
      People <strong data-testid="header-people-count">{people.length}</strong>
      {STATUSES.map((s) => (
        <span key={s}>
          {' '}· {s} <strong data-testid={`header-claims-${s}-count`}>{statusCount(claims, s)}</strong>
        </span>
      ))}
      {' '}· Due <strong data-testid="header-due-total">{dueTotal}</strong>
      {' '}· Overdue <strong data-testid="header-overdue-total">{overdueTotal}</strong>
    </header>
  );
}

export const contribution = SheetPanel.fill({ order: -10, Component: Header });
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson, RefusedError } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useUser } from '../session/useUser';
import { sheetKey, sheetQuery } from './sheetQuery';
import { periodsKey } from '../periods/periodsQuery';
import type { Sheet } from './sheetQuery';
import { useSheetToday } from './useSheetToday';
import { settingsQuery } from '../settings/settingsQuery';

function SheetToday({ sheetId }: { sheetId: string }) {
  const today = useSheetToday(sheetId);
  const archived = useQuery(sheetQuery(sheetId)).data?.archived;
  const parent = useQuery(settingsQuery(sheetId)).data?.parent ?? '';
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (date: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today: date }, user),
    onSuccess: async (sheet) => {
      queryClient.setQueryData(sheetKey(sheetId), sheet);
      // The change may have closed periods past their grace days.
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
    onError: (e) => setError(e instanceof RefusedError ? e.message : 'That is not a date (yyyy-mm-dd).'),
  });

  const archive = useMutation({
    mutationFn: () => putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/archive`, {}, user),
    onSuccess: (sheet) => queryClient.setQueryData(sheetKey(sheetId), sheet),
    onError: (e) => setError(e instanceof RefusedError ? e.message : 'The sheet could not be archived.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    once(() => save.mutateAsync(typed.trim()));
  };

  return (
    <form data-testid="sheet-today-form" onSubmit={submit}>
      Today <strong data-testid="sheet-today">{today}</strong>{' '}
      <label>
        Change to{' '}
        <input
          data-testid="sheet-today-input"
          placeholder="yyyy-mm-dd"
          value={typed}
          onChange={(e) => {
            setTyped(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save">
        Set today
      </button>{' '}
      Archived <strong data-testid="sheet-archived">{archived ? 'yes' : 'no'}</strong>{' '}
      Parent <strong data-testid="sheet-parent">{parent}</strong>{' '}
      <button
        type="button"
        data-testid="sheet-archive"
        onClick={() => {
          setError('');
          once(() => archive.mutateAsync());
        }}
      >
        Archive sheet
      </button>
      {error && <p data-testid="sheet-error">{error}</p>}
    </form>
  );
}

// Keyed by sheet, so a typed date or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 0,
  Component: ({ sheetId }) => <SheetToday key={sheetId} sheetId={sheetId} />,
});
import { getJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-mm-dd): use it, never the real clock, for anything dated.
 *  An `archived` sheet shows everything and refuses every change. */
export type Sheet = { id: string; today: string; archived: boolean };

/** Every query kept per sheet lives under this key, so re-loading a sheet re-reads all of it. */
export const sheetKey = (sheetId: string) => ['sheet', sheetId] as const;

export const sheetQuery = (sheetId: string) => ({
  queryKey: sheetKey(sheetId),
  queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
});
import { defineSlot } from '../Slot';

/**
 * The body of the loaded sheet. Every feature kept per sheet contributes its own panel here; it
 * is rendered only once a sheet has loaded, with the signed-in user and that sheet's id.
 */
export const SheetPanel = defineSlot<{ user: string; sheetId: string }>('sheet.panel');

