import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { forSlot } from '../../slots/registry';
import { claimsQuery } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { useSheetId } from './useSheetId';
import { sheetQuery } from './sheetQuery';

/** The loaded sheet: its id, then every per-sheet panel. Nothing shows until it, its people and its claims have loaded. */
export function ActiveSheet({ user }: { user: string }) {
  const [sheetId] = useSheetId();
  const sheet = useQuery({ ...sheetQuery(sheetId), enabled: sheetId !== '' });
  // Its people and claims are read before it shows, so a loaded sheet never shows its rows filling in later.
  const people = useQuery({ ...peopleQuery(sheetId), enabled: sheetId !== '' });
  const claims = useQuery({ ...claimsQuery(sheetId), enabled: sheetId !== '' });

  if (sheetId === '') return <p data-testid="sheet-none">No sheet loaded.</p>;
  if (sheet.isError) return <p data-testid="sheet-load-error">Could not load sheet {sheetId}.</p>;
  if (!sheet.data || people.isPending || claims.isPending) return <p data-testid="sheet-loading">Loading…</p>;

  return (
    <section data-testid="sheet">
      <h2>
        Sheet <span data-testid="sheet-current-id">{sheet.data.id}</span>
      </h2>
      <SheetPanel.Slot user={user} sheetId={sheet.data.id} />
      {forSlot(SheetPanel.id).length === 0 && <p data-testid="home-empty">Nothing here yet.</p>}
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { sheetQuery } from './sheetQuery';

/** The sheet's today (yyyy-mm-dd), or '' until loaded. Every default date uses this, never `new Date()`. */
export function useSheetToday(sheetId: string): string {
  return useQuery(sheetQuery(sheetId)).data?.today ?? '';
}
import { useSyncExternalStore } from 'react';

// The date this user's screen is shown as of (yyyy-mm-dd), '' when it shows the sheet as it is now. It
// belongs to this screen only: every request names it (X-As-Of, see http.ts), so the server answers a read
// as the store stood at the end of that date and refuses every change while it is set.
let asOf = '';
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** The as-of date the requests name now ('' for none). */
export function currentAsOf(): string {
  return asOf;
}

export function setAsOf(date: string): void {
  if (asOf === date) return;
  asOf = date;
  listeners.forEach((l) => l());
}

/** The as-of date shown on this screen ('' for none). */
export function useAsOf(): string {
  return useSyncExternalStore(subscribe, currentAsOf);
}
import { currentAsOf } from './asOf';

// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A write refused because the record was saved by someone else since it was loaded (409). */
export class ConflictError extends Error {}

/** A write refused by a rule the screen cannot see in full (422), e.g. a claim dated in a closed period; the message is the server's. */
export class RefusedError extends Error {}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  // A screen shown as of a date names it on every request: reads come back as of it, changes are refused (422).
  const asOf = currentAsOf();
  const res = await fetch(path, asOf ? { ...init, headers: { ...init?.headers, 'X-As-Of': asOf } } : init);
  if (res.status === 409) {
    throw new ConflictError(`${init?.method ?? 'GET'} ${path} -> 409`);
  }
  if (res.status === 422) {
    throw new RefusedError(await res.text());
  }
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
